# Family A-G: base grammar, escapes, classes, quantifiers, anchors, dot
P = []
def p(pat, subj=(), **k):
    k.update(pat=pat, subj=list(subj)); k.setdefault("feats", "all"); k.setdefault("id", "B%03d" % (len(P)+1)); P.append(k)
S = ["", "a", "ab", "aab", "xab\n", "a{", "a{x}", "a{,}", "a{1 2}", "aaaa", "{", "}", "]"]
# braces / literal brace
for pat in ["a{", "a{x}", "a{,}", "a{1 2}", "a{ 1 , 2 }", "a{,3}", "a{ ,2}", "a{1,2", "a{01}", "a{0}b", "a{2}{3}", "a**", "a{1}?",
            "{1}", "x{2,1}", "a{65535}", "a{65536}", "a{0,65535}", "a{,}b", "a{ }", "a{1,2 }", "a{\t1}", "a{1, }", "a{,0}", "a{0,0}",
            "a{00002}", "a{1,2}{3}", "a?+?", "a{1}+", "]", "}", "a|*b", "(*a", "*a", "a{-1}", "a{1,-2}", "a{ 1 }?", "a{+1}"]:
    p(pat, S + ["aaaaaaaaaa"])
# escapes
for pat in [r"\x412", r"\x", r"\x{}", r"\x{g}", r"\xg", r"\x{ 41 }", r"\x{4 1}", r"\x{41", r"\x{0000000041}", r"\x{ff}", r"\x{100}", r"\x{0ff}",
            r"\0377", r"\0", r"\07", r"\08", r"\377", r"\400", r"\777", r"\_", r"\a\e\f", r"\cA", r"\o{101}", r"\N{U+41}", r"\x{ 4 1 }",
            "\\\xe9", r"\-", r"\i", r"\y", r"\L", r"\u", r"\U", r"\F", r"\l", r"\N{name}", "a\\", r"\c", "\\x{\t41\t}", r"\012",
            r"\xA", r"\x{41}{2}", r"\101", r"\1010", r"\0101"]:
    p(pat, ["A", "AA", "A2", "\x07\x1b\x0c", "\xff", "\x00", "\x007", "\x008", "\x1f7", "_", "-", "\xe9", "\n", "\x0a", "\x10", "A0", "\x081"])
# classes
for pat in ["[]a]", "[^]a]", "[]", "[a-]", "[-a]", "[a-c-e]", r"[\d-z]", "[z-a]", r"[\x{41}-\x{43}]", r"[\t-\r]", r"[a-\x{7a}]", r"[\b]",
            r"[\0101]", r"[\101]", r"[\8]", r"[\g]", r"[\k<n>]", "[:alpha:]", "[[:alpha:]-z]", "[[:foo:]]", "[[:^alpha:]]", "[a&&b]",
            r"[\N]", r"[\R]", r"[\X]", r"[\B]", r"[\y]", "[[.a.]]", "[[=a=]]", r"[\w-.]", "[%--]", "[--0]", r"[a\-z]", r"[\]]", "[[]", "[a[]",
            "[[:alpha:][:digit:]]", "[[:alpha:]", "[]-a]", "[^-]", "[a-a]", r"[\x00]", r"[a-\d]", r"[\400]", r"[\377]", r"[\9]", "[[:alpha]",
            "[[:alpha:]b]", "[a-[:digit:]]", r"[\A]", r"[\K]", r"[\G]", r"[\Z]", r"[\z]", r"[\e-\r]", "[\\\\-a]", r"[\x5d]", "[-]", "[^]",
            "[]]", "[^^]", "[\\^]", r"[\c]", "[a-z-]", "[a-]z]", "[[:digit:]-]", "[-[:digit:]]", "[[:digit:]-[:alpha:]]", r"[\x{100}]",
            "[[:ascii:]]", "[[:word:]]", "[[:^word:]]", "[[:punct:]]", "[[:graph:]]", "[[:print:]]", "[[:cntrl:]]", "[[:blank:]]", "[[:space:]]",
            "[[:xdigit:]]", "[[:upper:]]", "[[:lower:]]", "[[:alnum:]]", "[[: alpha:]]", "[[:ALPHA:]]", "[[:alpha:]]]", r"[\Qa\E-c]", "[a-\\Qc\\E]"]:
    p(pat, ["a", "]", "-", "b", "d", "e", "z", "A", "C", "\x08", "\t", "\r", "8", "9", "g", "k", "<", "n", ">", ":", "&", ".", "%", "/", "0", "[",
            "\x00", "\xff", "\x7f", "\x0b", "\x85", "\xa0", "_", "^", "\\", "~", " ", "c", "B", "[a", "a]"])
# quantifiers, preference
for pat, sub in [("(a|ab)(c|bcd)(d*)", ["abcd"]), ("a*?b", ["aaab"]), ("a{2,3}?", ["aaaa"]), ("(a*)*b", ["b", "aab"]), ("(|a)+", ["aa"]),
                 ("(|a)+$", ["aa"]), ("((a)|(b))*", ["ab", "ba", "abba"]), ("(a)|b", ["b"]), ("(a{0})b", ["b"]), ("(?:){3}", ["", "x"]),
                 ("(a|)*", ["aa", "b"]), ("(a*)+", ["aaa", "b"]), ("(a?)*?b", ["aab"]), ("(a+)+b", ["aaab", "aaa"]), ("(a){2}", ["aa", "aaa"]),
                 ("(a|b){2,}c", ["abbc", "ac"]), ("(a|(b))+", ["ab", "ba"]), ("(?:(a)|b)*", ["ab", "ba"]), ("(a)*", ["aaa", ""]), ("(a|ab)*c", ["abac"]),
                 ("a||b", ["xb"]), ("(a|)+b", ["aab"]), ("(a?)+?b", ["aab"]), ("(a??)(a*)", ["aa"]), ("((a)|b)+", ["ab"]), ("(a)?(b)?(c)?$", ["bc", "c", ""]),
                 ("(a(b)?)+", ["aba"]), ("(?:a(b)?)+", ["aba"]), ("((a)|(b)|c)+", ["abc", "acb"]), ("(a){0}(b)", ["b"]), ("(?:(a)|(b)){2}", ["ab"]),
                 ("^(a\\1?)*$", ["aaa"]), ("(a*?)(a*)", ["aa"]), ("(a|b)*?c", ["abc"]), ("(?:a|b)*+c", ["abc"]), ("(a+|b+)*c", ["aabbc"]),
                 ("()", ["", "a"]), ("(()|a)+", ["a"]), ("(a|())+", ["ab"]), ("(?:()|a)*b", ["ab"]), ("(a*)*", ["b", "a"]), ("(a*)+?", ["aa"]),
                 ("(a{0,1}){3}", ["aa"]), ("(a?){3}b", ["ab"]), ("(?:(a)?){3}b", ["aab"]), ("(?:(a)|())*b", ["ab"]), ("x(a|ab|abc)*y", ["xabcaby"]),
                 ("(a)(?:(b)|c)*", ["abcb", "abc"]), ("(\\d+)(\\w+)", ["123abc"]), ("((a)b|a(b))*", ["abab", "ab"]),
                 ("(a|ab)(c|bcd)?(d*)", ["abcd", "abd"]), ("(?:a+?){2,3}", ["aaaa"]), ("(a{1,3}){2}", ["aaaa"]), ("(a{1,3}?){2}b", ["aaaab"])]:
    p(pat, sub)
# anchors and newlines (base ^ $, assertions)
for pat in ["^", "$", "a$", "^a", "a$\\n", "(?m)^a", "(?m)a$", "(?m)^$", "(?m)$", "\\Z", "\\z", "\\A", "a\\Z", "a\\z", "\\Gb", "^b", "(?m)^b",
            "$a", "a^", "x$\\n?", "(^)*a", "(?:$)?a", "^*", "a$?", "\\b*", "\\K+", "\\A+", "\\z?", "\\G*", "\\B{2}", "$+", "(?m)^{0}a",
            "(?m)$\\n$", "(?m)$\\n^", "\\Z\\n", "$$", "^^a", "(?m)\\Z", "(?m)\\A", "(?m)^\\n", ".$", "(?s).$", "(?m).$", "\\n$", "\\n\\Z", "(?m)^$\\n",
            "\\b", "\\B", "a\\b", "\\ba", "\\Ba", "a\\B"]:
    p(pat, [("a", 0), ("a\n", 0), ("a\n\n", 0), ("a\r\n", 0), ("ba", 1), ("\na", 1), ("\n\n", 1), ("ab", 1), ("b\nb", 2), ("", 0), ("\n", 0),
            ("a\nb\n", 0), ("a\nb\n", 3), ("ab", 2), ("aa", 1), ("x\n", 0)])
# dot / \N
for pat in [".", "(?s).", "\\N", "(?s)\\N", ".+", "(?s).+", "a.c", "[^a]", "\\N+", "\\N{2}", "\\N{1,}", "\\N{,2}"]:
    p(pat, ["\n", "\r", "\x85", "\x00", "\xff", "a\nc", "abc", "a\x00c"])
PROBES = P
